package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsIgnoreCase_TriageGen0Test {

    @Test
    public void testContainsIgnoreCase_NullStr() {
        assertFalse(StringUtils.containsIgnoreCase(null, "abc"));
    }

    @Test
    public void testContainsIgnoreCase_NullSearchStr() {
        assertFalse(StringUtils.containsIgnoreCase("abc", null));
    }

    @Test
    public void testContainsIgnoreCase_BothNull() {
        assertFalse(StringUtils.containsIgnoreCase(null, null));
    }

    @Test
    public void testContainsIgnoreCase_EmptyStr_EmptySearch() {
        // len = 0, max = 0. Loop runs once (i=0). regionMatches(false, 0, "", 0, 0) is true.
        assertTrue(StringUtils.containsIgnoreCase("", ""));
    }

    @Test
    public void testContainsIgnoreCase_EmptyStr_NonEmptySearch() {
        // len = 3, max = -3. Loop does not execute.
        assertFalse(StringUtils.containsIgnoreCase("", "abc"));
    }

    @Test
    public void testContainsIgnoreCase_NonEmptyStr_EmptySearch() {
        // len = 0, max = 3. Loop runs. regionMatches with length 0 is true.
        assertTrue(StringUtils.containsIgnoreCase("abc", ""));
    }

    @Test
    public void testContainsIgnoreCase_ExactMatchLower() {
        assertTrue(StringUtils.containsIgnoreCase("hello", "hello"));
    }

    @Test
    public void testContainsIgnoreCase_ExactMatchUpper() {
        assertTrue(StringUtils.containsIgnoreCase("HELLO", "hello"));
    }

    @Test
    public void testContainsIgnoreCase_MixedCaseMatch() {
        assertTrue(StringUtils.containsIgnoreCase("AbCdEfG", "cde"));
    }

    @Test
    public void testContainsIgnoreCase_SubstringMatch() {
        assertTrue(StringUtils.containsIgnoreCase("The Quick Brown Fox", "QUICK"));
    }

    @Test
    public void testContainsIgnoreCase_NoMatch() {
        assertFalse(StringUtils.containsIgnoreCase("abc", "def"));
    }

    @Test
    public void testContainsIgnoreCase_SearchLongerThanStr() {
        assertFalse(StringUtils.containsIgnoreCase("abc", "abcd"));
    }

    @Test
    public void testContainsIgnoreCase_MatchAtStart() {
        assertTrue(StringUtils.containsIgnoreCase("ApplePie", "apple"));
    }

    @Test
    public void testContainsIgnoreCase_MatchAtEnd() {
        assertTrue(StringUtils.containsIgnoreCase("ApplePie", "PIE"));
    }

    @Test
    public void testContainsIgnoreCase_MatchInMiddle() {
        assertTrue(StringUtils.containsIgnoreCase("aBcdE", "BCD"));
    }
}
